use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut pairs: Vec<(i64, i64)> = arr.iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    pairs.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));

    json!(pairs.iter().map(|(_, id)| *id).collect::<Vec<i64>>())
}
